#!/usr/bin/env python3
"""Simple Chrome DevTools Protocol helper."""
import json
import sys
import time
import urllib.request
import websocket

CDP_PORT = 1337


def list_targets():
    return json.loads(urllib.request.urlopen(f"http://localhost:{CDP_PORT}/json").read())


def find_target(url_substr=None, title_substr=None):
    for t in list_targets():
        if t.get("type") != "page":
            continue
        if url_substr and url_substr in t.get("url", ""):
            return t
        if title_substr and title_substr.lower() in t.get("title", "").lower():
            return t
    return None


class CDP:
    def __init__(self, ws_url):
        self.ws = websocket.create_connection(ws_url, timeout=30)
        self.id = 0

    def send(self, method, params=None, timeout=30):
        self.id += 1
        msg = {"id": self.id, "method": method, "params": params or {}}
        self.ws.send(json.dumps(msg))
        self.ws.settimeout(timeout)
        while True:
            data = json.loads(self.ws.recv())
            if data.get("id") == self.id:
                if "error" in data:
                    raise RuntimeError(data["error"])
                return data.get("result", {})

    def eval(self, expr, await_promise=False, timeout=30):
        r = self.send("Runtime.evaluate", {
            "expression": expr,
            "returnByValue": True,
            "awaitPromise": await_promise,
        }, timeout=timeout)
        if r.get("exceptionDetails"):
            raise RuntimeError(r["exceptionDetails"])
        return r.get("result", {}).get("value")

    def navigate(self, url):
        self.send("Page.enable")
        self.send("Page.navigate", {"url": url})

    def wait_load(self, max_seconds=30):
        end = time.time() + max_seconds
        while time.time() < end:
            state = self.eval("document.readyState")
            if state == "complete":
                return True
            time.sleep(0.4)
        return False

    def close(self):
        try:
            self.ws.close()
        except Exception:
            pass


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "list"
    if cmd == "list":
        for t in list_targets():
            print(t.get("type"), "|", t.get("title"), "|", t.get("url"))

